      everything(),
      list(
        sayi = ~ sum(is.na(.x)),
        oran = ~ mean(is.na(.x))
      )
    )
  ) |&gt;
  pivot_longer(
    everything(),
    names_to = c("degisken", ".value"),
    names_pattern = "(.*)_(sayi|oran)$"
  ) |&gt;
